function i(t){const e=new Date(t);return Number.isNaN(e.getTime())?t:e.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric",timeZone:"UTC"})+", "+e.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit",hour12:!1,timeZone:"UTC"})+" UTC"}function u(t){const e=new Date(t.length===10?`${t}T00:00:00Z`:t);return Number.isNaN(e.getTime())?t:e.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric",timeZone:"UTC"})}function m(t,e=Date.now()){const a=new Date(t).getTime();if(Number.isNaN(a))return"";const n=Math.max(0,Math.round((e-a)/6e4));if(n<1)return"just now";if(n<60)return`${n}m ago`;const r=Math.round(n/60);return r<24?`${r}h ago`:`${Math.round(r/24)}d ago`}export{u as a,i as f,m as t};
